CREATE SCHEMA IF NOT EXISTS messaging AUTHORIZATION spms_owner;

CREATE TABLE messaging.message_template (
    message_template_id            uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid,
    template_code                  text NOT NULL,
    purpose                        text NOT NULL,
    channel                        text NOT NULL,
    status                         text NOT NULL DEFAULT 'Draft',
    effective_from                 timestamptz NOT NULL DEFAULT now(),
    effective_to                   timestamptz,
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT message_template_pkey PRIMARY KEY (message_template_id),
    CONSTRAINT message_template_purpose_ck CHECK (purpose IN ('Confirmation', 'Reminder', 'Cancellation', 'IntakeRequest', 'Receipt', 'Waitlist', 'Marketing', 'Transactional')),
    CONSTRAINT message_template_channel_ck CHECK (channel IN ('Email', 'Sms', 'WhatsApp', 'Push')),
    CONSTRAINT message_template_version_ck CHECK (version >= 1),
    CONSTRAINT message_template_tenant_identity_uq UNIQUE (tenant_id, message_template_id),
    CONSTRAINT message_template_status_known CHECK (status IN ('Draft', 'Active', 'Retired')),
    CONSTRAINT message_template_effective_range_ck CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT message_template_code_uq UNIQUE NULLS NOT DISTINCT (tenant_id, property_id, template_code, channel)
);

CREATE TABLE messaging.message_template_version (
    message_template_version_id    uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid,
    message_template_id            uuid NOT NULL,
    version_number                 integer NOT NULL,
    locale                         text NOT NULL,
    subject                        text,
    body_template                  text NOT NULL,
    variables                      text[] NOT NULL DEFAULT '{}',
    provider_template_reference    text,
    approved_by                    uuid,
    approved_at                    timestamptz,
    status                         text NOT NULL DEFAULT 'Draft',
    effective_from                 timestamptz NOT NULL DEFAULT now(),
    effective_to                   timestamptz,
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT message_template_version_pkey PRIMARY KEY (message_template_version_id),
    CONSTRAINT message_template_version_version_number_ck CHECK (version_number >= 1),
    CONSTRAINT message_template_version_version_ck CHECK (version >= 1),
    CONSTRAINT message_template_version_tenant_identity_uq UNIQUE (tenant_id, message_template_version_id),
    CONSTRAINT message_template_version_status_known CHECK (status IN ('Draft', 'Approved', 'Active', 'Retired')),
    CONSTRAINT message_template_version_effective_range_ck CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT message_template_version_active_is_approved CHECK (status NOT IN ('Approved', 'Active') OR approved_by IS NOT NULL),
    CONSTRAINT message_template_version_number_uq UNIQUE (tenant_id, message_template_id, locale, version_number)
);
COMMENT ON COLUMN messaging.message_template_version.provider_template_reference IS 'WhatsApp/SMS provider-approved template id';

CREATE TABLE messaging.reminder_rule (
    reminder_rule_id               uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    property_id                    uuid,
    message_template_id            uuid NOT NULL,
    service_id                     uuid,
    trigger_event                  text NOT NULL,
    offset_minutes                 integer NOT NULL,
    respect_quiet_hours            boolean NOT NULL DEFAULT true,
    quiet_hours_start              time,
    quiet_hours_end                time,
    status                         text NOT NULL DEFAULT 'Active',
    effective_from                 timestamptz NOT NULL DEFAULT now(),
    effective_to                   timestamptz,
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT reminder_rule_pkey PRIMARY KEY (reminder_rule_id),
    CONSTRAINT reminder_rule_trigger_event_ck CHECK (trigger_event IN ('AppointmentConfirmed', 'BeforeStart', 'AfterCompletion', 'IntakeDue', 'WaitlistOffer')),
    CONSTRAINT reminder_rule_version_ck CHECK (version >= 1),
    CONSTRAINT reminder_rule_tenant_identity_uq UNIQUE (tenant_id, reminder_rule_id),
    CONSTRAINT reminder_rule_status_known CHECK (status IN ('Active', 'Retired')),
    CONSTRAINT reminder_rule_effective_range_ck CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT reminder_rule_quiet_pair CHECK ((quiet_hours_start IS NULL) = (quiet_hours_end IS NULL))
);
COMMENT ON COLUMN messaging.reminder_rule.service_id IS 'NULL = every service';
COMMENT ON COLUMN messaging.reminder_rule.offset_minutes IS 'negative = before the event';

CREATE TABLE messaging.scheduled_message (
