    scheduled_message_id           uuid NOT NULL,
    provider_code                  text NOT NULL,
    provider_message_id            text,
    delivery_state                 text NOT NULL,
    attempt_number                 smallint NOT NULL DEFAULT 1,
    provider_event_at              timestamptz,
    error_code                     text,
    idempotency_key                text NOT NULL,
    occurred_at                    timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    correlation_id                 text,
    CONSTRAINT message_delivery_pkey PRIMARY KEY (delivery_id, occurred_at),
    CONSTRAINT message_delivery_delivery_state_ck CHECK (delivery_state IN ('Queued', 'Sent', 'Delivered', 'Failed', 'Bounced', 'Undeliverable')),
    CONSTRAINT message_delivery_attempt_number_ck CHECK (attempt_number >= 1)
) PARTITION BY RANGE (occurred_at);
COMMENT ON TABLE messaging.message_delivery IS 'One row per delivery event (queued, sent, delivered, failed...). [delivery status callbacks]';

