    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT message_suppression_pkey PRIMARY KEY (message_suppression_id),
    CONSTRAINT message_suppression_channel_ck CHECK (channel IN ('Email', 'Sms', 'WhatsApp', 'Push')),
    CONSTRAINT message_suppression_suppression_reason_ck CHECK (suppression_reason IN ('OptOut', 'Bounce', 'Complaint', 'DoNotContact', 'Legal')),
    CONSTRAINT message_suppression_version_ck CHECK (version >= 1),
